#!/usr/bin/env python3
"""Page-specific Western history practice, authored and reviewed by an AI agent.

Seeds specify each concept, question and exact source span explicitly. No keyword
extraction or question-template expansion is used to invent additional items.

AI editorial review: every source page received either a coverage check or an
explicit exception. Imported OCR is not scan-verified. Inferred gichul texts
are excluded from new authorship. Same-page canonical/alias overlaps were
removed, and cross-page repeats were replaced with distinct concepts.
Selected quotations omit detected source issues including Roman religious
dates, New Deal election dates, Berlin blockade dates, Vulgate usage dates,
Pepin donation dates, and misleading adjoining dynasty succession text.
Coverage validation and a deterministic rerun check accompany the authoring.
This review is by an AI agent; it is not an expert or human certification.
"""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parents[2]
NOTES = {n['id']:n for n in json.loads((ROOT/'public/data/subjects/seoyangsa/notes.json').read_text())}
rows=[]
exclusions=[]

def page(value):
    return 'seoyangsa-' + ('gichul-page-'+value[1:] if value.startswith('g') else 'textbook-page-'+value)

def exclude(keys,reason):
    for key in keys.split(): exclusions.append({'page':page(key),'reason':reason})

def add(block):
    for line in block.strip().splitlines():
        fields=line.split('|')
        key,answer,prompt,quote=fields[:4]
        aliases=fields[4].split(';') if len(fields)>4 and fields[4] else []
        p=page(key);quote=quote.replace('\\n','\n')
        quotes=quote.split('§')
        assert all(q in NOTES[p]['text'] for q in quotes), (key,answer,quote)
        kind='short'
        if prompt=='C':
            kind='cloze';assert quote.count(answer)==1,(key,answer)
            prompt=quote.replace(answer,'_____',1)
        index=1+sum(q['page']==p for q in rows)
        row=dict(id=f'seoyangsa-page-practice-{kind}-{key}-{index}',page=p,kind=kind,prompt=prompt,answer=answer,acceptedAnswers=aliases,evidence=[dict(page=p,quote=q) for q in quotes],explain=f'{answer}: ' + quote.replace(chr(167), chr(10)).replace('<br>', chr(10)),topic=answer)
        if kind=='cloze':row['passage']=quote
        rows.append(row)

